/*
 * Lucky Vaults player app. Loads once, then only small JSON calls.
 * Screens live in memory: Lobby, Game (?g=Name), Chat sheet.
 * Uses the same backend as ChitPop: /chat/request, /chat/messages, /chat/send, /rewards/checkin.
 */
(function () {
    'use strict';

    var B = window.LV || {};
    var U = B.urls || {};
    var S = {
        games: B.games || [],
        paid: B.paid || [],
        me: B.me || null,
        filter: 'all',
        q: '',
        favs: read('lv_favs', []),
        since: B.now || 0,
        reqSeen: {},
        gameData: {},
        gameTimer: null,
        chatOpen: false,
        chatAfter: 0,
        chatTimer: null,
        unread: 0,
        cfg: B.cfg || {}
    };

    /* ---------------- helpers ---------------- */
    function $(id) { return document.getElementById(id); }
    function read(k, d) { try { var v = localStorage.getItem(k); return v ? JSON.parse(v) : d; } catch (e) { return d; } }
    function write(k, v) { try { localStorage.setItem(k, JSON.stringify(v)); } catch (e) { /* private mode */ } }

    // h('div', {class: 'x', onclick: fn}, [children | 'text'])
    function h(tag, attrs, kids) {
        var n = document.createElement(tag);
        if (attrs) {
            Object.keys(attrs).forEach(function (k) {
                var v = attrs[k];
                if (v === null || v === undefined || v === false) { return; }
                if (k === 'class') { n.className = v; }
                else if (k === 'html') { n.innerHTML = v; } // only for our own constant SVG icons
                else if (k.slice(0, 2) === 'on') { n.addEventListener(k.slice(2), v); }
                else { n.setAttribute(k, v === true ? '' : v); }
            });
        }
        (Array.isArray(kids) ? kids : (kids === undefined ? [] : [kids])).forEach(function (c) {
            if (c === null || c === undefined || c === false) { return; }
            n.appendChild(typeof c === 'string' || typeof c === 'number' ? document.createTextNode(String(c)) : c);
        });
        return n;
    }

    function api(url, opts) {
        opts = opts || {};
        var headers = { 'Accept': 'application/json', 'X-Requested-With': 'XMLHttpRequest' };
        if (opts.method && opts.method !== 'GET') { headers['X-CSRF-TOKEN'] = B.csrf; }
        return fetch(url, { method: opts.method || 'GET', body: opts.body, credentials: 'same-origin', headers: headers })
            .then(function (r) {
                if (r.status === 401 || r.status === 419) { openAuth('Please log in to continue'); throw new Error('auth'); }
                return r.json().catch(function () { return {}; }).then(function (d) {
                    if (!r.ok) { var e = new Error((d && d.message) || 'Something went wrong. Try again.'); e.data = d; throw e; }
                    return d;
                });
            });
    }

    function q(params) {
        return Object.keys(params).map(function (k) { return encodeURIComponent(k) + '=' + encodeURIComponent(params[k]); }).join('&');
    }

    function slugColor(name) {
        var pal = ['#5A2A1E', '#1F2D5C', '#3F1F55', '#1E4A45', '#2A2A4E', '#4A3A1A', '#503042', '#1D3B2A', '#3B2B5A', '#4A2230'];
        var n = 0;
        for (var i = 0; i < name.length; i++) { n = (n * 31 + name.charCodeAt(i)) % 9973; }
        return pal[n % pal.length];
    }
    function initials(name) {
        return name.split(/\s+/).filter(Boolean).slice(0, 2).map(function (w) { return w[0]; }).join('').toUpperCase();
    }
    function timeAgo(iso) {
        var s = Math.max(1, Math.round((Date.now() - new Date(iso).getTime()) / 1000));
        if (s < 60) { return 'just now'; }
        if (s < 3600) { return Math.round(s / 60) + 'm ago'; }
        if (s < 86400) { return Math.round(s / 3600) + 'h ago'; }
        return Math.round(s / 86400) + 'd ago';
    }
    function clock(iso) {
        try { return new Date(iso).toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' }); } catch (e) { return ''; }
    }
    function copy(text, label) {
        var done = function () { toast((label || 'Copied') + ' ✓'); beep('tap'); };
        if (navigator.clipboard && window.isSecureContext) {
            navigator.clipboard.writeText(text).then(done, function () { fallbackCopy(text); done(); });
        } else { fallbackCopy(text); done(); }
    }
    function fallbackCopy(text) {
        var t = h('textarea', { style: 'position:fixed;opacity:0' }, text);
        document.body.appendChild(t); t.select();
        try { document.execCommand('copy'); } catch (e) { /* ignore */ }
        t.remove();
    }

    /* ---------------- sound (made in the browser, no files) ---------------- */
    var actx = null;
    function beep(kind) {
        if (read('lv_mute', false)) { return; }
        try {
            var AC = window.AudioContext || window.webkitAudioContext;
            if (!AC) { return; }
            actx = actx || new AC();
            if (actx.state === 'suspended') { actx.resume(); }
            var notes = { tap: [[880, 0.05]], send: [[660, 0.07], [990, 0.09]], done: [[784, 0.09], [988, 0.09], [1318, 0.16]], msg: [[1046, 0.08], [1318, 0.1]] }[kind] || [[880, 0.05]];
            var t = actx.currentTime;
            notes.forEach(function (n) {
                var o = actx.createOscillator(), g = actx.createGain();
                o.type = 'sine'; o.frequency.value = n[0];
                g.gain.setValueAtTime(0.0001, t);
                g.gain.exponentialRampToValueAtTime(0.12, t + 0.01);
                g.gain.exponentialRampToValueAtTime(0.0001, t + n[1]);
                o.connect(g); g.connect(actx.destination);
                o.start(t); o.stop(t + n[1] + 0.02);
                t += n[1] * 0.9;
            });
        } catch (e) { /* no audio */ }
    }

    /* ---------------- toast ---------------- */
    var toastTimer = null;
    /* "Need help?" bubble pointing at Support */
    var helpTimer = null;
    function helpBubble(text, force, onTap) {
        if (!S.me || S.chatOpen || (!S.cfg.help && !force)) { return; }
        var old = $('helpTip'); if (old) { old.remove(); }
        var tip = h('div', { class: 'helptip', id: 'helpTip', role: 'button', tabindex: '0', onclick: function () { tip.remove(); document.body.classList.remove('help-glow'); if (onTap) { onTap(); } else { openChat(); } } }, [
            h('span', { class: 'ht' }, text || S.cfg.help),
            h('button', { class: 'hx', type: 'button', 'aria-label': 'Close', onclick: function (e) { e.stopPropagation(); tip.remove(); } }, '×')
        ]);
        document.body.appendChild(tip);
        document.body.classList.add('help-glow');
        clearTimeout(helpTimer);
        helpTimer = setTimeout(function () { tip.remove(); document.body.classList.remove('help-glow'); }, 8000);
    }
    var stuckTimer = null;
    function watchStuck(k) {
        clearTimeout(stuckTimer);
        if (k === 'deposit' || k === 'cashout') { stuckTimer = setTimeout(function () { if (viewKey() === k) { helpBubble(); } }, 30000); }
    }

    function toast(msg, err) {
        if (err) { setTimeout(function () { helpBubble(); }, 2800); }
        var t = $('toast');
        t.textContent = msg;
        t.className = 'toast show' + (err ? ' err' : '');
        clearTimeout(toastTimer);
        toastTimer = setTimeout(function () { t.className = 'toast' + (err ? ' err' : ''); }, 2600);
    }

    /* ---------------- icons (constant SVG) ---------------- */
    var I = {
        logo: '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#0B0B10" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="3" y="5" width="18" height="15" rx="2"/><circle cx="12" cy="12.5" r="3.5"/><path d="M12 9v1M12 15v1M8.5 12.5h1M14.5 12.5h1"/></svg>',
        user: '<svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true"><circle cx="12" cy="8" r="4"/><path d="M4 21c0-4 4-6 8-6s8 2 8 6"/></svg>',
        back: '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m15 5-7 7 7 7"/></svg>',
        search: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true"><circle cx="11" cy="11" r="7"/><path d="m20 20-3.5-3.5"/></svg>',
        star: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#F4EFE3" stroke-width="2" stroke-linejoin="round" aria-hidden="true"><path d="m12 3 2.7 5.6 6.1.9-4.4 4.3 1 6.1L12 17l-5.4 2.9 1-6.1-4.4-4.3 6.1-.9z"/></svg>',
        starOn: '<svg width="16" height="16" viewBox="0 0 24 24" fill="#E8B84A" stroke="#E8B84A" stroke-width="2" stroke-linejoin="round" aria-hidden="true"><path d="m12 3 2.7 5.6 6.1.9-4.4 4.3 1 6.1L12 17l-5.4 2.9 1-6.1-4.4-4.3 6.1-.9z"/></svg>',
        check: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m5 12 5 5 9-10"/></svg>',
        x: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" aria-hidden="true"><path d="M6 6l12 12M18 6 6 18"/></svg>',
        sound: '<svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M11 5 6 9H3v6h3l5 4z"/><path d="M15.5 8.5a5 5 0 0 1 0 7M18.5 5.5a9 9 0 0 1 0 13"/></svg>',
        plus: '<svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M12 8v8M8 12h8"/></svg>',
        wallet: '<svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="2" y="6" width="20" height="13" rx="2"/><path d="M16 12.5h2"/></svg>',
        gift: '<svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="3" y="9" width="18" height="12" rx="1.5"/><path d="M2 9h20M12 9v12M12 9S10 3 7 5s5 4 5 4M12 9s2-6 5-4-5 4-5 4"/></svg>',
        copy: '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="8" y="8" width="12" height="12" rx="2"/><path d="M16 8V5a1 1 0 0 0-1-1H5a1 1 0 0 0-1 1v10a1 1 0 0 0 1 1h3"/></svg>',
        mute: '<svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M11 5 6 9H3v6h3l5 4z"/><path d="m22 9-6 6M16 9l6 6"/></svg>'
    };

    /* ---------------- header ---------------- */
    function header(mode, title) {
        var hd = $('hdr');
        hd.textContent = '';
        hd.className = 'hdr' + (mode === 'back' ? ' inner' : '');
        if (mode === 'back') {
            hd.appendChild(h('div', { class: 'back' }, [
                h('button', { class: 'ibtn', type: 'button', 'aria-label': 'Back', html: I.back, onclick: back }),
                h('span', { style: 'white-space:nowrap;overflow:hidden;text-overflow:ellipsis' }, title)
            ]));
        }
        hd.appendChild(h('button', { class: 'logo', type: 'button', 'aria-label': (B.name || 'Lucky Vaults') + ' lobby', onclick: function () { S.filter = 'all'; go('/'); } },
            B.logo ? [h('img', { class: 'logo-img', src: B.logo, alt: B.name || 'Lucky Vaults' })] : [
                h('span', { class: 'logo-mark', html: I.logo }),
                h('span', { class: 'logo-name' }, B.name || 'Lucky Vaults')
            ]));
        // desktop menu
        var page = viewKey();
        var dn = h('nav', { class: 'dnav', 'aria-label': 'Menu' });
        [['lobby', 'Lobby'], ['mine', 'My games'], ['cashout', 'Cashout'], ['activity', 'Activity'], ['rules', 'Rules']].concat(S.cfg.ref && S.me ? [['invite', 'Invite']] : []).forEach(function (x) {
            dn.appendChild(h('button', { type: 'button', class: page === x[0] ? 'on' : '', onclick: function () { navTo(x[0]); } }, x[1]));
        });
        if (S.cfg.freeplay && S.me) {
            dn.appendChild(h('button', { type: 'button', class: page === 'free' ? 'on' : '', onclick: function () { navTo('free'); } }, '🎁 Free Play'));
        }
        dn.appendChild(h('button', { type: 'button', class: 'dep', onclick: function () { navTo('deposit'); } }, '+ Deposit'));
        hd.appendChild(dn);
        if (mode !== 'back') { hd.appendChild(h('span', { class: 'grow' })); }

        var muted = read('lv_mute', false);
        hd.appendChild(h('button', {
            class: 'ibtn', type: 'button', 'aria-label': muted ? 'Sound off' : 'Sound on', html: muted ? I.mute : I.sound,
            onclick: function () { write('lv_mute', !read('lv_mute', false)); header(mode, title); if (!read('lv_mute', false)) { beep('tap'); } }
        }));
        if (S.me) {
            hd.appendChild(h('button', { class: 'ibtn', type: 'button', 'aria-label': 'My account', html: I.user, onclick: function () { go('/?me=1'); } }));
        } else {
            hd.appendChild(h('button', { class: 'btn btn-gold btn-sm', type: 'button', style: 'height:42px', onclick: function () { openAuth(); } }, 'Sign up'));
        }
    }

    /** One step back (game -> deposit -> back = game), lobby when there is nothing to go back to. */
    function back() {
        beep('tap');
        if (S.depth > 0) { history.back(); } else { S.filter = 'all'; go('/'); }
    }

    function crumb() {
        return h('button', { class: 'crumb', type: 'button', onclick: back }, [h('span', { html: I.back }), 'Back']);
    }

    function viewKey() {
        var p = new URLSearchParams(location.search);
        if (p.get('g')) { return 'game'; }
        if (p.get('deposit')) { return 'deposit'; }
        if (p.get('cashout')) { return 'cashout'; }
        if (p.get('rules')) { return 'rules'; }
        if (p.get('free')) { return 'free'; }
        if (p.get('install')) { return 'install'; }
        if (p.get('me')) { return 'me'; }
        if (p.get('activity')) { return 'activity'; }
        if (p.get('invite')) { return 'invite'; }
        return S.filter === 'mine' ? 'mine' : 'lobby';
    }

    function navTo(k, extra) {
        beep('tap');
        var needLogin = ['deposit', 'cashout', 'chat', 'activity'].indexOf(k) !== -1;
        if (needLogin && !S.me) { openAuth(); return; }
        if (k === 'lobby') { S.filter = 'all'; go('/'); }
        else if (k === 'mine') { S.filter = 'mine'; go('/'); }
        else if (k === 'chat') { openChat(); }
        else if (k === 'app') { if (inviteTab()) { go('/?invite=1'); } else { installPopup(); } }
        else { go('/?' + q(Object.assign({}, extra || {}, (function () { var o = {}; o[k] = 1; return o; })()))); }
    }

    /* ---------------- invite friends ---------------- */
    function inviteTab() { return !!(S.me && S.cfg.ref && standalone()); }
    function inviteLink() { return location.origin + '/r/' + ((S.me && S.me.ref && S.me.ref.code) || S.me.code || ''); }
    function shareInvite(btn) {
        var link = inviteLink();
        var text = 'Join me on ' + (B.name || 'Lucky Vaults') + '. Sign up with my link:';
        if (navigator.share) { navigator.share({ title: B.name || 'Lucky Vaults', text: text, url: link }).catch(function () {}); return; }
        copy(link, 'Invite link copied');
    }
    function inviteView() {
        if (!S.me) { openAuth('Sign up to invite friends'); return; }
        header('back', 'Invite friends');
        setNav('app');
        var r = S.me.ref || {};
        var v = h('div', { class: 'view form-wrap' }, [crumb()]);
        if (!S.cfg.ref) {
            v.appendChild(h('div', { class: 'card muted' }, 'Invites are not open right now. Chat with us for offers.'));
            swap(v); return;
        }
        v.appendChild(h('div', { style: 'text-align:center;padding:8px 0' }, [
            h('span', { class: 'promo-ic', style: 'margin:0 auto 12px', html: I.gift }),
            h('div', { class: 'page-h' }, 'Invite friends'),
            h('div', { class: 'muted', style: 'margin-top:8px;line-height:1.45' }, S.cfg.ref)
        ]));
        v.appendChild(h('div', { class: 'card', style: 'display:flex;gap:8px;align-items:center' }, [
            h('div', { class: 'grow bold', style: 'word-break:break-all;font-size:14px' }, inviteLink()),
            h('button', { class: 'btn btn-dark', type: 'button', onclick: function () { copy(inviteLink(), 'Invite link copied'); } }, 'Copy')
        ]));
        v.appendChild(h('button', { class: 'btn btn-gold btn-block', type: 'button', style: 'height:54px;font-size:16px', onclick: function (e) { shareInvite(e.currentTarget); } }, 'Share my invite link'));
        v.appendChild(h('div', { class: 'card limits' }, [
            h('div', null, [h('div', { class: 'k' }, 'Invited'), h('div', { class: 'v' }, String(r.invited || 0))]),
            h('div', null, [h('div', { class: 'k' }, 'Deposited'), h('div', { class: 'v' }, String(r.deposited || 0))]),
            h('div', null, [h('div', { class: 'k' }, 'Bonus'), h('div', { class: 'v', style: 'font-size:12.5px' }, 'After their first deposit')])
        ]));
        v.appendChild(h('div', { class: 'muted small', style: 'line-height:1.5' }, '1. Share your link · 2. Your friend signs up with it · 3. After their first deposit is loaded, you both get a bonus. One bonus per friend.'));
        swap(v);
    }
    function inviteCard() {
        if (!S.me || !S.cfg.ref) { return null; }
        return h('button', { class: 'card invite-card', type: 'button', onclick: function () { navTo('invite'); } }, [
            h('span', { class: 'promo-ic', html: I.gift }),
            h('div', { class: 'grow', style: 'text-align:left' }, [h('div', { class: 'bold' }, 'Invite friends, get Free Play'), h('div', { class: 'small muted' }, 'You both get a bonus after their first deposit')]),
            h('span', { class: 'btn btn-gold', style: 'padding:8px 14px' }, 'Invite')
        ]);
    }

    function profile() {
        if (!S.me) { openAuth(); return; }
        header('back', 'My account');
        setNav('');
        swap(h('div', { class: 'view form-wrap' }, [
            crumb(),
            h('div', { class: 'card' }, [
                h('div', { class: 'bold', style: 'font-size:18px' }, S.me.name || 'Player'),
                h('div', { class: 'muted small' }, 'Player ID ' + (S.me.code || ''))
            ]),
            h('button', { class: 'btn btn-dark btn-block', type: 'button', onclick: function () { navTo('activity'); } }, 'My activity'),
            S.cfg.ref ? h('button', { class: 'btn btn-dark btn-block', type: 'button', onclick: function () { navTo('invite'); } }, 'Invite friends · ' + ((S.me.ref && S.me.ref.invited) || 0) + ' invited') : null,
            h('button', { class: 'btn btn-dark btn-block', type: 'button', onclick: function () { navTo('install'); } }, 'Install the app & notifications'),
            h('button', { class: 'btn btn-dark btn-block', type: 'button', onclick: function () { navTo('rules'); } }, 'Rules'),
            h('button', { class: 'btn btn-dark btn-block', type: 'button', onclick: function () { openChat(); } }, 'Chat with support'),
            h('form', { method: 'POST', action: U.logout }, [
                h('input', { type: 'hidden', name: '_token', value: B.csrf }),
                h('button', { class: 'btn btn-line btn-block', type: 'submit' }, 'Log out')
            ])
        ]));
    }

    /* ---------------- router ---------------- */
    function go(url) {
        if (url !== location.pathname + location.search) {
            S.depth = (S.depth || 0) + 1;
            history.pushState({ d: S.depth }, '', url);
        }
        render();
        window.scrollTo(0, 0);
    }
    window.addEventListener('popstate', function (e) {
        S.depth = e.state && e.state.d ? e.state.d : 0;
        closeModal();
        if (S.chatOpen) { closeChat(); }
        render();
    });

    function render() {
        stopGamePoll();
        var p = new URLSearchParams(location.search);
        var k = viewKey();
        if (k === 'game') { gameView(p.get('g')); return; }
        watchStuck(k);
        if (k === 'deposit' && S.me) { depositView(p.get('game') || ''); return; }
        if (k === 'cashout' && S.me) { cashoutView(p.get('game') || ''); return; }
        if (k === 'rules') { rulesView(); return; }
        if (k === 'free') { freeView(); return; }
        if (k === 'install') { installView(); return; }
        if (k === 'me' && S.me) { profile(); return; }
        if (k === 'activity' && S.me) { activityView(); return; }
        if (k === 'invite') { inviteView(); return; }
        lobbyView();
    }

    function swap(node) {
        var v = $('view');
        v.textContent = '';
        v.appendChild(node);
    }

    function setNav(key) {
        Array.prototype.forEach.call(document.querySelectorAll('[data-nav]'), function (b) {
            b.classList.toggle('on', b.getAttribute('data-nav') === key);
        });
    }

    /* ---------------- lobby ---------------- */
    function lobbyView() {
        header('home');
        setNav(S.filter === 'mine' ? 'mine' : 'lobby');
        var v = h('div', { class: 'view' });
        var cfg = S.cfg;

        if (!S.me) {
            v.appendChild(h('div', { class: 'hero-banner' }, [
                h('div', { class: 'grow' }, [
                    h('div', { class: 't' }, cfg.welcome || 'Sign up & get your welcome bonus'),
                    h('div', { class: 's' }, 'Sign up in 20 seconds · real people help you 24/7')
                ]),
                h('button', { class: 'btn btn-gold', type: 'button', onclick: function () { openAuth(); } }, 'Sign up')
            ]));
            v.appendChild(h('div', { class: 'how' }, [
                h('div', null, [h('b', null, '1'), 'Sign up']),
                h('div', null, [h('b', null, '2'), cfg.freeplay ? 'Get Free Play' : 'Pick a game']),
                h('div', null, [h('b', null, '3'), 'Play & cash out'])
            ]));
            var trust = [h('span', null, [h('i', { class: 'live-dot' }), (cfg.hours || 'Support online')])];
            if (cfg.avgLoad) { trust.push(h('span', null, '⚡ Coins load in ~' + cfg.avgLoad + ' min')); }
            var outs = (cfg.methods || []).filter(function (m) { return m.cashout; }).map(function (m) { return m.name; });
            if (cfg.paidCount) { trust.push(h('span', null, '✓ ' + cfg.paidCount + ' cashouts paid ' + ({ 7: 'this week', 30: 'this month' }[cfg.paidDays] || 'in 48h'))); }
            else if (outs.length) { trust.push(h('span', null, '✓ Cash out to ' + outs.slice(0, 2).join(' & '))); }
            v.appendChild(h('div', { class: 'trust' }, trust));
        } else {
            v.appendChild(liveStrip());
            var fc = freePlayCard();
            if (fc) { v.appendChild(fc); }
            var ic = inviteCard();
            if (ic) { v.appendChild(ic); }
            v.appendChild(quickCards());
        }

        var mine = myGames();
        if (mine.length) {
            v.appendChild(h('div', null, [
                h('p', { class: 'lbl' }, 'Your games'),
                h('div', { class: 'chips' }, mine.map(function (g) {
                    return h('button', { class: 'chip mine', type: 'button', onclick: function () { beep('tap'); go('/?' + q({ g: g })); } }, [h('span', { class: 'live' }), g]);
                }))
            ]));
        }

        var input = h('input', { placeholder: 'Search games', 'aria-label': 'Search games', value: S.q, type: 'search', oninput: function () { S.q = input.value; drawGrid(); } });
        var hasCats = S.games.some(function (g) { return g.cat === 'fish' || g.cat === 'slots'; });
        var hasHot = S.games.some(function (g) { return g.hot; });
        var filters = [['all', 'All']];
        if (hasCats) { filters.push(['fish', 'Fish'], ['slots', 'Slots']); }
        if (hasHot) { filters.push(['hot', '🔥 HOT']); }
        if (S.me) { filters.push(['mine', 'Mine']); }
        filters.push(['fav', '⭐ Saved']);
        var chipRow = h('div', { class: 'chips' });
        filters.forEach(function (f) {
            chipRow.appendChild(h('button', {
                class: 'chip' + (S.filter === f[0] ? ' on' : ''), type: 'button',
                onclick: function () { S.filter = f[0]; lobbyView(); }
            }, f[1]));
        });
        v.appendChild(h('div', { class: 'lobby-tools', style: 'display:flex;flex-direction:column;gap:12px' }, [
            h('label', { class: 'search' }, [h('span', { html: I.search }), input]),
            chipRow
        ]));

        v.appendChild(h('div', { class: 'grid', id: 'grid' }));

        if (S.paid.length) {
            var p = S.paid[0];
            var ticker = h('span', { class: 'ticker' }, paidText(p));
            v.appendChild(h('div', { class: 'okcard paid' }, [
                h('span', { html: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#3DD68C" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m5 12 5 5 9-10"/></svg>' }),
                h('span', { class: 'ttl' }, 'Recently paid'),
                ticker
            ]));
            rotatePaid(ticker);
        }

        swap(v);
        if (window.innerWidth >= 900) {
            var tools = v.querySelector('.lobby-tools');
            tools.style.flexDirection = 'row';
        }
        drawGrid();
    }

    function paidText(p) { return p.name + ' · ' + p.amount + (p.game ? ' · ' + p.game : '') + ' · ' + timeAgo(p.at); }

    var paidTimer = null;
    function rotatePaid(el) {
        clearInterval(paidTimer);
        if (S.paid.length < 2) { return; }
        var i = 0;
        paidTimer = setInterval(function () {
            if (!document.body.contains(el)) { clearInterval(paidTimer); return; }
            i = (i + 1) % S.paid.length;
            el.textContent = paidText(S.paid[i]);
        }, 3500);
    }

    function quickCards() {
        var row = h('div', { class: 'quick' });
        var rd = lastDeposit();
        if (rd) {
            row.appendChild(h('button', { class: 'card', type: 'button', onclick: function () { navTo('deposit', { game: rd.game, again: 1 }); } }, [
                h('div', { class: 't' }, 'Deposit ' + money(rd.amount) + ' again'),
                h('div', { class: 'muted small' }, rd.method.name + ' · ' + rd.game)
            ]));
        }
        var ck = S.me.checkin;
        if (ck) {
            var b = h('button', { class: 'card', type: 'button', onclick: function () { checkin(b); } }, [
                h('div', { class: 't' }, 'Daily check-in'),
                h('div', { class: 'muted small' }, ck.next ? 'Day ' + ck.next + ' ready — tap' : 'Done today ✓')
            ]);
            row.appendChild(b);
        }
        row.appendChild(h('button', { class: 'card', type: 'button', onclick: function () { navTo('deposit'); } }, [
            h('div', { class: 't' }, 'Deposit'),
