    function checkin(btn) {
        if (!S.me.checkin || !S.me.checkin.next) { toast('Already checked in today. Come back tomorrow!'); return; }
        btn.disabled = true;
        api(U.checkin, { method: 'POST', body: new FormData() }).then(function (d) {
            beep('done');
            toast(d.message || 'Checked in!');
            S.me.checkin = { done: d.day, next: null };
            lobbyView();
        }).catch(function (e) { toast(e.message, true); btn.disabled = false; });
    }

    function myGames() { return (S.me && S.me.games) || []; }

    function drawGrid() {
        var grid = $('grid');
        if (!grid) { return; }
        grid.textContent = '';
        var mine = myGames();
        var term = S.q.trim().toLowerCase();
        var list = S.games.filter(function (g) {
            if (term && g.name.toLowerCase().indexOf(term) === -1) { return false; }
            if (S.filter === 'mine') { return mine.indexOf(g.name) !== -1; }
            if (S.filter === 'fav') { return S.favs.indexOf(g.name) !== -1; }
            if (S.filter === 'fish' || S.filter === 'slots') { return g.cat === S.filter; }
            if (S.filter === 'hot') { return !!g.hot; }
            return true;
        });
        if (!list.length) {
            grid.appendChild(h('div', { class: 'empty', style: 'grid-column:1/-1' },
                S.filter === 'mine' ? 'No game accounts yet. Pick a game and tap PLAY.' : (S.filter === 'fav' ? 'Tap ☆ on a game to save it here.' : 'No games found.')));
            return;
        }
        artN = 0;
        list.forEach(function (g) { grid.appendChild(tile(g, mine.indexOf(g.name) !== -1)); });
    }

    function tile(g, isMine) {
        var fav = S.favs.indexOf(g.name) !== -1;
        var img = gameArt(g, 'img');
        if (g.hot) { img.appendChild(h('span', { class: 'hot2' }, 'HOT')); }
        if (isMine) { img.appendChild(h('span', { class: 'tag' }, 'MINE')); }
        img.appendChild(h('button', {
            class: 'fav', type: 'button', 'aria-label': fav ? 'Remove from saved' : 'Save game', html: fav ? I.starOn : I.star,
            onclick: function (e) {
                e.stopPropagation();
                var i = S.favs.indexOf(g.name);
                if (i === -1) { S.favs.push(g.name); } else { S.favs.splice(i, 1); }
                write('lv_favs', S.favs);
                beep('tap');
                drawGrid();
            }
        }));
        var open = function () { beep('tap'); go('/?' + q({ g: g.name })); };
        return h('div', { class: 'tile', role: 'button', tabindex: '0', 'aria-label': 'Play ' + g.name, onclick: open, onkeydown: function (e) { if (e.key === 'Enter') { open(); } } }, [
            img,
            h('div', { class: 'nm' }, g.name),
            h('div', { class: 'ct' }, catLabel(g.cat).replace('&', '&')),
            h('div', { class: 'play' }, [h('span', { html: '<svg width="13" height="13" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M7 4v16l13-8z"/></svg>' }), 'PLAY'])
        ]);
    }

    /* ---------------- game hub ---------------- */
    function gameOf(name) { return S.games.filter(function (x) { return x.name === name; })[0] || { name: name, icon: null, cat: 'other' }; }
    function catLabel(c) { return c === 'fish' ? 'FISH' : (c === 'slots' ? 'SLOTS' : 'SLOTS & FISH'); }

    var artN = 0;
    function gameArt(g, cls) {
        var box = h('div', { class: cls, style: 'background:' + slugColor(g.name) }, [initials(g.name)]);
        if (g.icon) {
            var first = artN++ < 8;
            var img = h('img', { src: g.icon, alt: '', width: '360', height: '360', decoding: 'async', loading: first ? 'eager' : 'lazy', fetchpriority: first ? 'high' : null });
            img.style.opacity = '0';
            img.addEventListener('load', function () { img.style.transition = 'opacity .15s'; img.style.opacity = '1'; });
            if (img.complete) { img.style.opacity = '1'; }
            box.appendChild(img);
        }
        return box;
    }

    function gameView(name) {
        header('back', name);
        setNav('lobby');
        var body = h('div', { id: 'gameBody', class: 'hub' }, [
            h('div', { class: 'sk', style: 'height:130px' }),
            h('div', { class: 'sk', style: 'height:200px' })
        ]);
        swap(h('div', { class: 'view hub-wrap' }, [crumb(), body]));
        if (!S.me) { drawGame(name, { guest: true }); return; }
        if (S.gameData[name]) { drawGame(name, S.gameData[name]); }
        loadGame(name);
    }

    function loadGame(name) {
        return api(U.game + '?' + q({ name: name })).then(function (d) {
            var before = S.gameData[name];
            S.gameData[name] = d;
            if (d.request && d.request.id) { S.reqSeen[d.request.id + ':' + d.request.status] = 1; }
            if (current() !== name) { return; }
            var nowReady = d.account && !(before && before.account);
            if (before && nowReady) {
                beep('done');
                toast('Your ' + name + ' account is ready! 🎮');
                if (S.me.games.indexOf(name) === -1) { S.me.games.push(name); }
            }
            drawGame(name, d);
            schedGamePoll(name, d);
        }).catch(function (e) { if (e.message !== 'auth') { toast(e.message, true); } });
    }

    function current() { return new URLSearchParams(location.search).get('g'); }

    function schedGamePoll(name, d) {
        stopGamePoll();
        var open = d.request && (d.request.status === 'pending' || d.request.status === 'processing');
        if (open) { S.gameTimer = setTimeout(function () { if (!document.hidden) { loadGame(name); } else { schedGamePoll(name, d); } }, 4000); }
    }
    function stopGamePoll() { clearTimeout(S.gameTimer); S.gameTimer = null; }

    function hubTop(g, badge, sub, action) {
        return h('div', { class: 'hub-top' }, [
            gameArt(g, 'hub-art'),
            h('div', { class: 'hub-info' }, [
                h('span', { class: 'hub-cat' }, catLabel(g.cat)),
                h('div', { class: 'hub-name' }, g.name),
                badge,
                sub ? h('div', { class: 'muted small', style: 'line-height:1.45' }, sub) : null,
                action || null
            ])
        ]);
    }

    function drawGame(name, d) {
        var box = $('gameBody');
        if (!box) { return; }
        box.textContent = '';
        var g = gameOf(name);
        var req = d.request;

        if (d.guest) {
            box.appendChild(hubTop(g, null, 'Sign up with your phone number. Our team creates your ' + name + ' login in minutes.',
                h('button', { class: 'btn btn-gold btn-block', type: 'button', style: 'height:52px', onclick: function () { openAuth('Sign up to play ' + name); } }, 'Sign up to play')));
            return;
        }

        // ---- ready: Play + login + coin actions
        if (d.account) {
            var acc = d.account;
            var play = h('button', { class: 'btn btn-gold btn-block hub-play', type: 'button', onclick: function () {
                beep('tap');
                if (g.link) {
                    copy(acc.username, 'Username copied — paste it in ' + name);
                    window.open(g.link, '_blank', 'noopener');
                } else {
                    copy(acc.username, 'Username copied — open ' + name + ' and paste');
                }
            } }, [h('span', { html: '<svg width="18" height="18" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M7 4v16l13-8z"/></svg>' }), 'Play ' + name]);
            box.appendChild(hubTop(g, h('div', { class: 'small bold', style: 'color:var(--ok)' }, '● Your account is active'), null, play));

            var login = h('div', { class: 'card hub-card' }, [h('div', { class: 'hub-h' }, 'Your login')]);
            login.appendChild(credRow('Game username', acc.username, 'Username copied'));
            if (acc.password) { login.appendChild(credRow('Game password', acc.password, 'Password copied')); }
            box.appendChild(login);

            box.appendChild(h('div', { class: 'card hub-card' }, [
                h('div', { class: 'hub-h' }, 'How to play ' + name),
                h('div', { class: 'howto' }, [
                    h('div', null, [h('span', { class: 'num' }, '1'), g.link ? 'Tap "Play ' + name + '" — it opens / downloads the game' : 'Open the ' + name + ' app or site']),
                    h('div', null, [h('span', { class: 'num' }, '2'), 'Log in with the username & password above (tap Copy)']),
                    h('div', null, [h('span', { class: 'num' }, '3'), 'Load coins here — they show in the game in minutes']),
                    g.note ? h('div', { class: 'muted small', style: 'padding-left:30px' }, g.note) : null
                ])
            ]));
            var t = (S.me && S.me.tasks) || {};
            var acts = h('div', { class: 'card hub-card' }, [
                h('div', { class: 'hub-h' }, 'Coins'),
                h('div', { class: 'hub-acts' }, [
                    h('button', { class: 'act gold', type: 'button', onclick: function () { navTo('deposit', { game: name }); } }, [h('span', { html: I.plus }), 'Load coins']),
                    h('button', { class: 'act', type: 'button', onclick: function () { navTo('cashout', { game: name }); } }, [h('span', { html: I.wallet }), 'Cashout']),
                    h('button', { class: 'act green', type: 'button', onclick: function () { navTo('free', { game: name }); } }, [h('span', { html: I.gift }), 'Free Play'])
                ]),
                S.cfg.freeplay && !t.claimed ? h('div', { class: 'small bold', style: 'color:var(--ok)' }, t.installed && t.push ? '🎁 Your Free Play is ready to claim!' : 'Install the app + turn on notifications to unlock your Free Play:') : null,
                S.cfg.freeplay && !t.claimed && !(t.installed && t.push) ? h('div', { class: 'row', style: 'gap:8px' }, [
                    t.installed || standalone() ? null : h('button', { class: 'btn btn-dark grow', type: 'button', style: 'height:42px', onclick: function () { installPopup(); } }, '📱 Install app'),
                    t.push ? null : h('button', { class: 'btn btn-gold grow', type: 'button', style: 'height:42px', onclick: function (e) { if (isIOS() && !standalone()) { installPopup(); return; } enablePush(e.currentTarget).then(function (ok) { if (ok) { render(); } }); } }, '🔔 Turn on alerts')
                ]) : null,
                req && req.type === 'reset' && (req.status === 'pending' || req.status === 'processing')
                    ? h('div', { class: 'small muted' }, '⏳ Password reset requested · ' + clock(req.at))
                    : h('button', { class: 'linkbtn', type: 'button', onclick: function (e) { resetPassword(name, e.currentTarget); } }, 'Forgot password? Reset it')
            ]);
            box.appendChild(acts);
            return;
        }

        // ---- account being set up
        if (req && req.type === 'new_account' && (req.status === 'pending' || req.status === 'processing')) {
            var st = req.status;
            box.appendChild(hubTop(g, h('span', { class: 'pend' }, [h('i'), 'Account pending']), 'Your login will appear right here the moment it is ready.', null));
            var steps = [
                ['Request received', req.at ? clock(req.at) : 'Done', 'ok'],
                ['Creating your account', st === 'done' ? 'Done' : 'Our team is on it', st === 'done' ? 'ok' : 'now'],
                ['Ready to play', st === 'done' ? 'Loading your login…' : 'Your login appears here', st === 'done' ? 'ok' : '']
            ];
            var list = h('div', { class: 'steps' });
            steps.forEach(function (s, i) {
                list.appendChild(h('div', { class: 'stp ' + s[2] }, [
                    h('span', { class: 'c', html: s[2] === 'ok' ? I.check : null }, s[2] === 'ok' ? null : (s[2] === 'now' ? h('i', { class: 'spin' }) : String(i + 1))),
                    h('span', null, [h('span', { class: 't' }, (i + 1) + '. ' + s[0]), h('span', { class: 's' }, s[1])])
                ]));
            });
            box.appendChild(h('div', { class: 'card hub-card', style: 'align-items:center;text-align:center' }, [
                h('div', { class: 'ring', html: '<svg width="34" height="34" viewBox="0 0 24 24" fill="none" stroke="#E8B84A" stroke-width="2" stroke-linecap="round" aria-hidden="true"><circle cx="12" cy="12" r="8"/><path d="M12 8v4l3 2"/></svg>' }),
                h('div', { class: 'pill-line' }, 'Status: account creation in progress'),
                h('div', { class: 'hub-title' }, 'Your ' + name + ' account is being set up'),
                h('div', { class: 'muted small' }, 'This usually takes a few minutes. We\'ll notify you.'),
                list
            ]));
            box.appendChild(h('button', { class: 'btn btn-gold btn-block', type: 'button', style: 'height:52px', onclick: function () { navTo('deposit', { game: name }); } }, 'Load coins while you wait'));
            box.appendChild(h('div', { class: 'row', style: 'gap:8px' }, [
                h('button', { class: 'btn btn-dark grow', type: 'button', onclick: function () { openChat(); } }, 'Support'),
                h('button', { class: 'btn btn-dark grow', type: 'button', onclick: function () { go('/'); } }, 'Other games')
            ]));
            return;
        }

        // ---- no account yet
        var note = req && req.type === 'new_account' && req.status === 'rejected'
            ? h('div', { class: 'card small', style: 'border-color:#5A2A22' }, 'Your last request could not be completed. Check Support for the reason, or try again.') : null;
        box.appendChild(hubTop(g, null, 'No ' + name + ' account yet. One tap and our team creates it — your username and password appear right here.',
            h('button', { class: 'btn btn-gold btn-block', type: 'button', style: 'height:52px', onclick: function (e) { createAccount(name, e.currentTarget); } }, 'Create my account')));
        if (note) { box.appendChild(note); }
        box.appendChild(h('button', { class: 'linkbtn', type: 'button', onclick: function () { openChat('I already have a ' + name + ' account'); } }, 'I already have an account'));
    }

    function credRow(label, value, done) {
        return h('div', { class: 'cred2' }, [
            h('div', { class: 'k' }, label),
            h('div', { class: 'row', style: 'gap:8px' }, [
                h('div', { class: 'v' }, value),
                h('button', { class: 'cp', type: 'button', 'aria-label': 'Copy ' + label, html: I.copy, onclick: function () { copy(value, done); } })
            ])
        ]);
    }

    function createAccount(name, btn) {
        btn.disabled = true;
        btn.textContent = 'Sending…';
        beep('send');
        var fd = new FormData();
        fd.append('type', 'new_account');
        fd.append('game', name);
        api(U.account, { method: 'POST', body: fd }).then(function (d) {
            var gd = S.gameData[name] || {};
            gd.request = d.request || { type: 'new_account', status: 'pending', status_label: 'Pending', at: new Date().toISOString() };
            S.gameData[name] = gd;
            toast('✅ Request sent! Our team is creating your ' + name + ' account.');
            setTimeout(function () { notifyCard(false); }, 1500);
            drawGame(name, gd);
            schedGamePoll(name, gd);
            window.scrollTo(0, 0);
        }).catch(function (e) {
            toast(e.message, true);
            btn.disabled = false;
            btn.textContent = 'Create my account';
        });
    }

    function resetPassword(name, btn) {
        btn.disabled = true;
        var fd = new FormData();
        fd.append('type', 'reset');
        fd.append('game', name);
        api(U.account, { method: 'POST', body: fd }).then(function () {
            beep('send');
            toast('Password reset requested ✓ We\'ll update you here.');
            loadGame(name);
        }).catch(function (e) { toast(e.message, true); btn.disabled = false; });
    }

    /* ---------------- deposit ---------------- */
    function gameSelect(selected, onlyMine) {
        var mine = myGames();
        var sel = h('select', { class: 'sel', 'aria-label': 'Game' });
        sel.appendChild(h('option', { value: '' }, 'Pick a game'));
        var names = onlyMine ? mine.slice() : mine.concat(S.games.map(function (g) { return g.name; }).filter(function (n) { return mine.indexOf(n) === -1; }));
        names.forEach(function (n) {
            sel.appendChild(h('option', { value: n, selected: n === selected ? 'selected' : null }, n + (mine.indexOf(n) !== -1 ? '  ✓' : '')));
        });
        if (!selected && mine.length === 1) { sel.value = mine[0]; }
        return sel;
    }

    function money(n) { return '$' + (Math.round(n * 100) % 100 ? n.toFixed(2) : String(Math.round(n))); }

    function depositView(game) {
        header('back', 'Deposit');
        setNav('deposit');
        var methods = S.cfg.methods || [];
        var st = { method: methods[0] || null, amount: null, file: null };
        var again = new URLSearchParams(location.search).get('again') ? lastDeposit() : null;
        if (again) { st.method = again.method; st.amount = again.amount; }
        var v = h('div', { class: 'view form-wrap' }, [crumb()]);
        if (!methods.length) {
            v.appendChild(h('div', { class: 'card' }, [
                h('div', { class: 'bold' }, 'Deposit methods are being set up'),
                h('div', { class: 'muted small', style: 'margin:4px 0 12px' }, 'Message us and we\'ll help you deposit right away.'),
                h('button', { class: 'btn btn-gold btn-block', type: 'button', onclick: function () { openChat('I want to deposit'); } }, 'Chat with us')
            ]));
            swap(v);
            return;
        }

        var sel = gameSelect(game, false);
        var mgrid = h('div', { class: 'mgrid' });
        var amts = h('div', { class: 'amts' });
        var minTxt = h('span', { class: 'small bold', style: 'color:var(--gold)' });
        var other = h('input', { class: 'txt hide', type: 'number', inputmode: 'decimal', placeholder: 'Amount in $', min: '1', step: '1' });
        var payBtn = h('button', { class: 'btn btn-gold btn-block', type: 'button' });
        var hint = h('div', { class: 'muted small', style: 'text-align:center' });
        var fileIn = h('input', { type: 'file', accept: 'image/*', class: 'hide' });
        var drop = h('label', { class: 'drop' }, [h('span', { html: '<svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 8h3l2-3h6l2 3h3v11H4z"/><circle cx="12" cy="13" r="3.5"/></svg>' }), h('span', null, 'Upload payment screenshot'), fileIn]);
        var submit = h('button', { class: 'btn btn-gold btn-block', type: 'button', disabled: true, style: 'height:54px;font-size:16px' }, 'Submit deposit');

        var minAll = Math.min.apply(null, methods.map(function (m) { return m.min; }));
        function presets(m) { return (m && m.amounts) || []; }
        function presetOf(m, a) { return presets(m).filter(function (p) { return Math.abs(p.a - a) < 0.001; })[0] || null; }
        function chips() {
            var p = presets(st.method);
            if (p.length) { return p.map(function (x) { return x.a; }); }
            return minAll < 5 ? [1, 5, 10, 25, 50] : [5, 10, 25, 50, 100];
        }
        function draw() {
            mgrid.textContent = '';
            methods.forEach(function (m) {
                var on = st.method && st.method.id === m.id;
                var range = presets(m).length ? money(m.min) + ' – ' + money(m.max) : 'Any amount from ' + money(m.min);
