    function b64ToBytes(s) {
        var pad = '='.repeat((4 - s.length % 4) % 4);
        var raw = atob((s + pad).replace(/-/g, '+').replace(/_/g, '/'));
        var out = new Uint8Array(raw.length);
        for (var i = 0; i < raw.length; i++) { out[i] = raw.charCodeAt(i); }
        return out;
    }

    /** Ask permission, subscribe this device, save it. Resolves true when on. */
    function enablePush(btn, quiet, renew) {
        var j;
        var key = (document.querySelector('meta[name=pd-vapid]') || {}).content;
        if (!('serviceWorker' in navigator) || !('PushManager' in window) || !window.Notification || !key) {
            if (quiet) { return Promise.resolve(false); }
            toast(isIOS() && !standalone() ? 'On iPhone: first add the app to your Home Screen, then open it and turn on notifications.' : 'Notifications are not supported in this browser.', true);
            return Promise.resolve(false);
        }
        if (btn) { btn.disabled = true; }
        return Notification.requestPermission().then(function (perm) {
            if (perm !== 'granted') { throw new Error('Notifications are blocked. Allow them in your browser settings.'); }
            return navigator.serviceWorker.register('/sw.js', { scope: '/' }).then(function () { return navigator.serviceWorker.ready; });
        }).then(function (reg) {
            var fresh = function () { return reg.pushManager.subscribe({ userVisibleOnly: true, applicationServerKey: b64ToBytes(key) }); };
            return reg.pushManager.getSubscription().then(function (sub) {
                if (!sub) { return fresh(); }
                // only when the push service said it is dead (or the key changed): throw it away and make a new one
                var oldKey = sub.options && sub.options.applicationServerKey ? btoa(String.fromCharCode.apply(null, new Uint8Array(sub.options.applicationServerKey))).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '') : '';
                if (renew || (oldKey && oldKey !== key.replace(/=+$/, ''))) {
                    return sub.unsubscribe().catch(function () {}).then(fresh);
                }
                return sub;
            });
        }).then(function (sub) {
            j = sub.toJSON();
            return fetch(U.pushSub, {
                method: 'POST', credentials: 'same-origin',
                headers: { 'Content-Type': 'application/json', 'Accept': 'application/json', 'X-CSRF-TOKEN': B.csrf },
                body: JSON.stringify({ endpoint: j.endpoint, keys: j.keys })
            });
        }).then(function (r) {
            if (!r.ok) { throw new Error('Could not turn on notifications. Try again.'); }
            if (!U.pushCheck) { return r; }
            // button: send one real notification to this phone. silent re-sync: only ask "is this one known dead?"
            return fetch(U.pushCheck, {
                method: 'POST', credentials: 'same-origin',
                headers: { 'Content-Type': 'application/json', 'Accept': 'application/json', 'X-CSRF-TOKEN': B.csrf },
                body: JSON.stringify({ endpoint: j.endpoint, probe: quiet ? 1 : 0 })
            }).then(function (c) { return c.json(); }).catch(function () { return { ok: true }; }).then(function (c) {
                if (c && (c.dead || c.status === 404 || c.status === 410)) {
                    // dead subscription: make a brand-new one once
                    if (!renew) { return enablePush(btn, quiet, true).then(function (ok) { if (!ok) { throw new Error(''); } return 'done'; }); }
                    if (quiet) { throw new Error(''); }
                    throw new Error('Your phone is blocking alerts for Lucky Vaults. Open phone Settings → Apps → Lucky Vaults → Notifications → Allow, then try again.');
                }
                return r;
            });
        }).then(function (r) {
            if (r === 'done') { return true; }
            if (!quiet) { beep('done'); toast('Notifications are on 🔔'); }
            if (S.me) { S.me.tasks = S.me.tasks || {}; S.me.tasks.push = true; }
            var nc = $('ncard'); if (nc) { nc.remove(); }
            if (['lobby', 'mine', 'free', 'game'].indexOf(viewKey()) > -1) { setTimeout(render, 50); }
            return true;
        }).catch(function (e) {
            if (quiet) { return false; }
            if (e.message) { toast(e.message, true); }
            if (btn) { btn.disabled = false; }
            return false;
        });
    }

