    function pollChat(first) {
        clearTimeout(S.chatTimer);
        api(U.chatMessages + '?' + q({ after: S.chatAfter })).then(function (d) {
            var box = $('msgs');
            if (first && !S.chatAfter) { box.textContent = ''; }
            var gotAgent = false;
            (d.messages || []).forEach(function (m) {
                if (m.id <= S.chatAfter) { return; }
                S.chatAfter = m.id;
