    function bubble(m) {
        var mine = m.from === 'player';
        if (m.req) {
            var r = m.req;
            return h('div', { class: 'm req ' + (mine ? 'me' : 'them') }, [
                h('div', { class: 'row', style: 'justify-content:space-between;gap:12px' }, [
