        el.textContent = recent ? '● ' + name + ' is online' : '● ' + name + ' · usually replies in minutes';
    }

    function sendChat(e) {
        e.preventDefault();
        var input = $('msgIn');
        var text = input.value.trim();
        var file = $('photo').files[0];
        if (!text && !file) { return; }
        var fd = new FormData();
        if (text) { fd.append('body', text); }
        if (file) { fd.append('attachment', file); }
        input.value = '';
        $('photo').value = '';
        beep('send');
        var temp = h('div', { class: 'm me', style: 'opacity:.6' }, [text || 'Sending photo…']);
        $('msgs').appendChild(temp);
        $('msgs').scrollTop = $('msgs').scrollHeight;
        api(U.chatSend, { method: 'POST', body: fd }).then(function (d) {
            temp.remove();
            (d.messages || []).forEach(function (m) {
                if (m.id <= S.chatAfter) { return; }
                S.chatAfter = m.id;
