    /* ---------------- background check (unread + request updates) ---------------- */
    function bgPoll() {
        if (!S.me || document.hidden) { setTimeout(bgPoll, 15000); return; }
        api(U.poll + '?' + q({ since: S.since })).then(function (d) {
            if (d.now) { S.since = d.now - 5; }
            if (d.popup && !S.chatOpen) { beep('msg'); openChat(); }
            if (!S.chatOpen && typeof d.unread === 'number') {
                if (d.unread > S.unread) { beep('msg'); helpBubble('New message from support. Tap to read', true); }
                setUnread(d.unread);
            }
            if (d.requests && d.requests.length) { mergeLive(d.requests); }
            (d.requests || []).forEach(function (r) {
                var key = r.id + ':' + r.status;
                if (S.reqSeen[key] || (r.status !== 'done' && r.status !== 'rejected')) { return; }
                S.reqSeen[key] = 1;
                {
                    beep(r.status === 'done' ? 'done' : 'msg');
                    toast((r.status === 'done' ? '✅ ' : '❌ ') + (r.label || 'Request') + (r.game ? ' · ' + r.game : '') + ' — ' + (r.status_label || r.status));
                    if (r.game && current() === r.game) { loadGame(r.game); }
                    if (r.status === 'done' && r.type === 'redeem' && S.cfg.ref) { setTimeout(function () { helpBubble('Enjoying ' + (B.name || 'Lucky Vaults') + '? Invite a friend and you both get Free Play', true, function () { navTo('invite'); }); }, 3500); }
                    if (r.status === 'done' && r.type === 'new_account' && r.game && S.me.games.indexOf(r.game) === -1) { S.me.games.push(r.game); }
