                else if (t.indexOf('cashout') > -1) { navTo('cashout'); }
                else { navTo('activity'); }
            });
        });
        document.addEventListener('keydown', function (e) { if (e.key === 'Escape' && S.chatOpen) { closeChat(); } });
        document.addEventListener('visibilitychange', function () {
            if (!document.hidden && current()) { loadGame(current()); }
        });

        // installable app + push (same service worker as ChitPop, its own scope on this domain)
        if ('serviceWorker' in navigator) { navigator.serviceWorker.register('/sw.js', { scope: '/' }).catch(function () {}); }
        // Always re-save THIS phone's subscription when alerts are allowed (server may only have an old /
        // other-device / ChitPop one, or Chrome may have rotated the endpoint). Silent, once per app open.
        if (S.me && window.Notification && Notification.permission === 'granted') {
            setTimeout(function () { enablePush(null, true); }, 800);
        }
        if (S.me && standalone() && !(S.me.tasks && S.me.tasks.installed) && !read('lv_inst_sent', false)) {
            write('lv_inst_sent', true);
            reportTask('installed');
        }

        var p = new URLSearchParams(location.search);
        var openNow = p.get('chat');
        var appPop = p.get('app');
        if (appPop) { history.replaceState({}, '', '/'); setTimeout(function () { installPopup(); }, 500); }
        if (p.get('login') && !S.me) { history.replaceState({}, '', '/'); setTimeout(function () { openAuth(); }, 300); }
        if (openNow) { history.replaceState({}, '', '/'); }
        render();
        if (openNow && S.me) { openChat(); }
        else if (S.me && viewKey() === 'lobby') {
            setTimeout(function () {
                if (promoPopup()) { return; }
                var t = S.me.tasks || {};
                var today = new Date().toDateString();
                if (read('lv_help_day', '') !== today) { write('lv_help_day', today); setTimeout(function () { helpBubble(); }, 1800); }
                if (read('lv_new', 0)) { write('lv_new', 0); toast('🎉 Welcome! Install the app + turn on alerts to get your Free Play.'); return; }
                setTimeout(function () { notifyCard(false); }, 2500);
            }, 900);
        }
        if (S.me) { setTimeout(bgPoll, 4000); }
        if (inviteTab()) { // installed app: the "App" tab becomes "Invite"
            var ab = document.querySelector('[data-nav="app"]');
            if (ab) { ab.innerHTML = '<span style="display:inline-flex">' + I.gift + '</span>Invite'; }
        }
    }

    if (document.readyState === 'loading') { document.addEventListener('DOMContentLoaded', init); } else { init(); }
})();

